{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "Token",
    "displayName": "Token",
    "category": "Content",
    "keywords": [
      "token",
      "chip",
      "tag",
      "pill",
      "label",
      "removable",
      "dismissible",
      "filter chip",
      "closable"
    ],
    "props": [
      {
        "name": "label",
        "type": "string",
        "description": "Text label displayed inside the token.",
        "required": true
      },
      {
        "name": "size",
        "type": "'sm' | 'md' | 'lg'",
        "description": "The size of the token.",
        "default": "'md'"
      },
      {
        "name": "color",
        "type": "'default' | 'red' | 'orange' | 'yellow' | 'green' | 'teal' | 'cyan' | 'blue' | 'purple' | 'pink' | 'gray'",
        "description": "Color variant of the token.",
        "default": "'default'"
      },
      {
        "name": "icon",
        "type": "ReactNode",
        "description": "Optional icon rendered before the label.",
        "slotElements": [
          {
            "__element": "Icon",
            "props": {
              "icon": "check",
              "size": "sm"
            }
          }
        ]
      },
      {
        "name": "isDisabled",
        "type": "boolean",
        "description": "Whether the token is disabled; reduces opacity and blocks interactions.",
        "default": "false"
      },
      {
        "name": "onRemove",
        "type": "(e: React.MouseEvent) => void",
        "description": "Callback fired when the remove button is clicked. When provided, an X button is rendered inside the token."
      },
      {
        "name": "onClick",
        "type": "(e: React.MouseEvent) => void",
        "description": "Click handler. When provided, the token renders as a <span> container with an invisible <button> inside for accessibility."
      },
      {
        "name": "href",
        "type": "string",
        "description": "Link URL. When provided, the token renders as an <a> element. The destination follows the shared navigation rule described on the Link `href` prop."
      },
      {
        "name": "description",
        "type": "string",
        "description": "Accessible description applied via aria-description on the root element."
      },
      {
        "name": "endContent",
        "type": "ReactNode",
        "description": "Content rendered after the label and before the remove button.",
        "slotElements": [
          {
            "__element": "Icon",
            "props": {
              "icon": "chevronDown",
              "size": "sm"
            }
          },
          {
            "__element": "Badge",
            "props": {
              "label": "3"
            }
          }
        ]
      },
      {
        "name": "isLabelHidden",
        "type": "boolean",
        "description": "Visually hides the label using a screen-reader-only clip technique; the label remains accessible.",
        "default": "false"
      },
      {
        "name": "xstyle",
        "type": "StyleXStyles",
        "description": "StyleX styles for layout customization (margins, positioning, sizing). Must be a stylex.create() value, not an inline style object like style={{}}."
      }
    ],
    "theming": {
      "targets": [
        {
          "className": "astryx-token",
          "visualProps": [
            "color",
            "size"
          ],
          "states": [
            "disabled"
          ]
        }
      ]
    },
    "usage": {
      "description": "Token is a small, inline element for representing discrete pieces of associated data, like tags, categories, or selections. Use it to label content, show active filters, or represent removable items like selected recipients in a compose field.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Use color to distinguish categories (for example, green for \"Active\", red for \"Blocked\", blue for \"In Review\") so users can scan status at a glance."
        },
        {
          "guidance": true,
          "description": "Provide an onRemove callback when tokens represent user selections that can be undone, like filters or multi-select values."
        },
        {
          "guidance": true,
          "description": "Add a leading icon when it helps identify the token type faster, like a person icon for user tokens or a tag icon for labels."
        },
        {
          "guidance": true,
          "description": "Keep labels short: one to three words. Tokens truncate with ellipsis when the text overflows."
        },
        {
          "guidance": false,
          "description": "Don't use tokens for primary actions or navigation; use Button or Link instead. Tokens are for displaying metadata, not triggering workflows."
        },
        {
          "guidance": false,
          "description": "Don't hide the label unless the icon alone is universally understood. A color dot without text is ambiguous."
        },
        {
          "guidance": false,
          "description": "Don't mix too many colors in one token group. Stick to two or three meaningful colors so the palette stays scannable."
        }
      ],
      "anatomy": [
        {
          "name": "Icon",
          "required": false,
          "description": "A leading icon that identifies the token type, like a user avatar or category symbol."
        },
        {
          "name": "Label",
          "required": true,
          "description": "The visible text. Also used as the accessible name when isLabelHidden is true."
        },
        {
          "name": "End content",
          "required": false,
          "description": "Trailing content after the label, like a count badge or status dot."
        },
        {
          "name": "Remove button",
          "required": false,
          "description": "An X button that appears when onRemove is provided, letting users dismiss the token."
        }
      ]
    },
    "package": "@astryxdesign/core",
    "import": "@astryxdesign/core/Token",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
